mapper.select:
select ai.id album_id, ai.cover_url, ai.album_title, ai.include_track_count, max(if(stat.stat_type='0401', stat_num, 0)) play_stat_num, max(if(stat.stat_type='0402', stat_num, 0)) subscribe_stat_num, max(if(stat.stat_type='0403', stat_num, 0)) buy_stat_num, max(if(stat.stat_type='0404', stat_num, 0)) comment_stat_num from album_info ai inner join album_stat stat on stat.album_id = ai.id and stat.is_deleted = 0
and ai.user_id = #{vo.userId}
and ai.status = #{vo.status}
and ai.album_title like CONCAT('%', #{vo.albumTitle}, '%')
group by ai.id order by ai.create_time desc
